class Service {
  constructor(name, role) {
    this.name = name;
    this.role = role;
  }
  getDetails() {
    return `${this.name} (${this.role})`;
  }
}
const s = new Service('Alice', 'Engineer');
const execute = s.getDetails;
console.log(execute());

async function compute(n) {
  if (n < 10) {
    throw new Error('below_threshold');
  }
  return n * 3;
}

compute(25)
  .catch(() => 200)
  .then(val => {
    console.log(val + 1);
  });

